import json,pickle
from shapely.geometry import mapping
res=pickle.load(open('res5.pkl','rb'))
LIC='All rights reserved by source; approximate traced derivative, shown with attribution pending community permission'
NOTE="Traced approximately from the official map; always check the community's official map and status before relying on it"
S=[
('cin','cincinnati-eruv-perimeter','Cincinnati Eruv (Nov 2025 map)','Cincinnati','US','OH','us-oh-cincinnati','Cincinnati Eruv (cincinnatieruv.org)','https://www.cincinnatieruv.org/','https://www.cincinnatieruv.org/wp-content/uploads/2025/12/Eruv-Map-November-2025-1.pdf','Outer boundary of the official PDF map "Eruv Map November 2025" (raster base map). Registered to OpenStreetMap by edge-gradient template matching of the map base against an OSM tile mosaic (scale ~1.46 px per z16 px) and checked visually; estimated precision +/-30-40 m. The "Excluded by Construction" pink area inside the boundary is not subtracted.'),
('mem','memphis-eruv-perimeter','Eruv of Memphis','Memphis','US','TN','us-tn-memphis','Baron Hirsch Congregation, Memphis (baronhirsch.org)','https://www.baronhirsch.org/eruvofmemphis.html','https://images.shulcloud.com/16677/uploads/Website-Photos/EruvMap2024withnotes.png','Lavender area of the official 2024 PNG map ("EruvMap2024withnotes"). Registered to OpenStreetMap with 8 street-intersection control points (initial residual 20-60 m) followed by bounded road-raster refinement against OSM; estimated precision +/-20-30 m. Annotation text on the map is ignored.'),
('oma','omaha-eruv-perimeter','Omaha Eruv','Omaha','US','NE','us-ne-omaha','Beth Israel Synagogue, Omaha (orthodoxomaha.org)','https://www.orthodoxomaha.org/erev.html','https://www.orthodoxomaha.org/erev.html','Red/orange/green boundary line (electric line, non-electric line, JCC fence) of the official Google-Maps-style boundary image on the eruv page (about S 132nd St to S 118th St, W Center Rd to north of Westover Rd). Registered with 5 street-intersection control points (S 132nd/S 126th/S 118th x Pacific St, W Center Rd) plus road refinement against OSM; the overlay of OSM roads matches the base map; estimated precision +/-15 m. Vertices placed by hand along the drawn line.'),
('pot','potomac-eruv-perimeter','Potomac Community Eruv','Potomac','US','MD','us-md-potomac','Young Israel Ezras Israel of Potomac (yieip.org)','https://www.yieip.org/potomaceruv','https://www.yieip.org/potomaceruv','Area inside the blue line of the official satellite-image map (Falls Rd/MD 189, I-270, Bells Mill Rd, Democracy Blvd/Westlake Dr). Registered to OpenStreetMap with 5 control points (MD 189 x Bells Mill, MD 189 x Montrose, Bells Mill x Gainsborough, I-270 x MD 189, I-270 x Montrose; affine fit, residuals 1-127 m on hand-picked points) and verified by overlaying OSM roads on the image (MD 189, I-270, Bells Mill align); estimated precision +/-40 m. The line was traced to its centre.'),
('ind','indianapolis-eiruv-perimeter','Indianapolis Eiruv','Indianapolis','US','IN','us-in-indianapolis',"Congregation B'nai Torah, Indianapolis (btorahindy.org)",'https://www.btorahindy.org/faqs/','https://www.btorahindy.org/faqs/','Red line of the official satellite map PDF linked from the FAQ (W 79th St, Spring Mill Rd, W 64th St, Grandview Dr, Ditch Rd). Registered to OpenStreetMap with 7 street-intersection control points (affine fit, residuals 5-31 m) and verified by overlaying OSM roads; estimated precision +/-30 m.'),
]
feats=[]
for k,i,n,c,co,st,rep,src,su,bu,ex in S:
    if k not in res: print('skip',k); continue
    p=dict(id=i,name_en=n,city=c,country=co,state=st,geometry_kind='perimeter',status='unknown',source=src,source_url=su,boundary_map_url=bu,license=LIC,verified_at='2026-10-17',geometry_precision='approximate',note=NOTE+' ('+ex+')',replaces_id=rep)
    g=res[k]['geom']; assert g.geom_type=='Polygon' and g.is_valid,k
    feats.append({'type':'Feature','properties':p,'geometry':mapping(g)})
json.dump({'type':'FeatureCollection','features':feats},open('./batch5-eruvs.geojson','w'),separators=(',',':'))
print(len(feats),[(f['properties']['id'],len(f['geometry']['coordinates'][0])-1) for f in feats])
